cd "$TESTBED_BOUNDARY" && python -c "
from databricks.sdk import WorkspaceClient
w = WorkspaceClient()
print('--- catalogs ---')
for c in w.catalogs.list():
    print(c.name)
print('--- schemas in workspace ---')
try:
  for s in list(w.schemas.list(catalog_name='workspace'))[:30]:
    print(s.full_name)
except Exception as e:
  print('err', e)
"

cd "$TESTBED_BOUNDARY" && python -c "
from databricks.sdk import WorkspaceClient
w = WorkspaceClient()
print('--- spark versions (LTS ML) ---')
try:
  for v in w.clusters.spark_versions().versions:
    if 'ML' in v.name or 'ml' in v.key:
      print(v.key, '|', v.name)
except Exception as e:
  print('err',e)
print('--- node types (first few) ---')
try:
  nts = w.clusters.list_node_types().node_types
  for nt in nts[:5]:
    print(nt.node_type_id, nt.num_cores, nt.memory_mb)
except Exception as e:
  print('err',e)
"
